-- 신조어 16개 추가 (2026-09-08 아침 검수 2차, 운영자 승인).
-- 전부 후보 테이블(slang_candidates)에 없던 단어로, 운영자가 직접 지시하고 이 세션에서
-- 웹 용례를 확인한 뒤 작성했다. 확인 근거는 아래에 남긴다.
--
--   외모정병  연세춘추·데일리안·psytimes·한국일보. '정병'이 환자 비하어라 usage에 경고를 넣었다.
--   야르바이트 브라보마이라이프 '요즘말 사전'. 기존 표제어 야르(104)에서 파생.
--   진지충    -충 접미사 계열. 이미 slang 에 있는 씹선비·한남충과 같은 성격이라 slang 으로 분류.
--   나일리지  아시아경제·서울경제 신조어 사전, 브라보마이라이프.
--   틀딱      노인 혐오 표현. 스시녀·김치녀·한남충과 같은 '차별적 비하 표현' 계열이라 slang.
--   풀청      팬덤 스밍 용어(더쿠 스밍 가이드, 나무위키 총공). 재생바를 건드리지 않는 완청.
--   찍먹/부먹 탕수육 소스 논쟁에서 굳은 짝. 찍먹은 '살짝만 맛보다'는 두 번째 뜻이 갈라져 나와
--             운영자 지시대로 뜻 2개로 실었다.
--   따라/아라 카페 주문 줄임말(따뜻한 라떼/아이스 라떼). 아아·따아 계열이 라떼로 넓어진 것으로,
--             카페 종사자의 실제 용례 증언으로 확인. 아라는 사람 이름과 겹쳐 usage에 주의를 적었다.
--   개꿀      개- 강조 + 꿀. 기존 개이득(11)과 같은 계열.
--   고트      GOAT(Greatest Of All Time)의 한글 표기. CLAUDE.md 표기 변이 규칙에 따라 국내에서 더
--             흔한 한글 '고트'를 표제어로, 'GOAT'를 aliases 로 넣어 어느 쪽으로 검색해도 항목 하나.
--   풀악셀/급발진 자동차 어휘에서 온 비유 한 쌍.
--   멘탈증발/뇌정지 기존 멘붕(123)과 근의어지만 조어가 달라 별도 표제어로 두고 related_words 로 묶었다.
--
-- 슬랭 분류 기준: 욕설·성적 표현은 없으나 진지충·틀딱은 사람을 벌레/신체 특징에 빗대 낮잡는
-- 비하어라 기존 slang 항목(씹선비·한남충·김치녀)의 선례를 따라 slang 으로 두고, short_desc 앞에
-- 대괄호 경고를 붙이는 기존 표기 관행을 그대로 지켰다.
--
-- id는 423부터 — 386~409는 20260908090000_add_thirtytwo_love_words.sql 이 선점한 번호이고
-- 410~422는 같은 날 1차분(20260908100000)이 썼다.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, category, short_desc, pronunciation, short_desc_i18n, origin, origin_i18n, usage, usage_i18n, romanization, meanings, related_words, aliases, likes, saves, translations) values
('423', '외모정병', 'new-slang', '[민감] 외모 강박에서 오는 불안을 자조하는 말', '[외모정병]',
 '{"en": "[sensitive] Self-mocking name for looks-driven anxiety", "ja": "[取り扱い注意] 外見強迫からくる不安を自嘲する語", "es": "[sensible] Nombre autoirónico para la ansiedad por el aspecto", "vi": "[nhạy cảm] Cách tự giễu nỗi lo ám ảnh ngoại hình", "de": "[sensibel] Selbstironischer Name für Aussehens-Angst"}'::jsonb,
 '「외모」와 「정병」(정신병의 속된 줄임말)을 합친 말. 2024년부터 오르다 2025년 이후 급격히 퍼졌다. 「취준정병」처럼 정신적 고통을 자조적 유머로 부르는 -정병 계열 조어의 하나로, 보정 앱과 짧은 영상이 일상이 된 환경에서 젊은 세대가 겪는 외모 강박을 스스로 이름 붙인 말이다.',
 '{"en": "외모 (looks) + 정병, a crude clipping of 정신병 (mental illness). It climbed from 2024 and spread fast after 2025, one of a family of -정병 coinages (like 취준정병, job-hunt edition) in which young people give their own distress a darkly funny name — here, the looks anxiety of a filtered, short-video everyday life.", "ja": "「외모(外見)」と、精神病の俗な略語である「정병」を合わせた語。2024年から増え2025年以降に急拡散した。「취준정병(就活精神病)」など、精神的な苦しみを自嘲的なユーモアで呼ぶ -정병 系の造語の一つで、加工アプリと短尺動画が日常になった環境での外見強迫に若者自身が付けた名前。", "es": "외모 (aspecto) + 정병, recorte vulgar de 정신병 (enfermedad mental). Creció desde 2024 y se disparó tras 2025; pertenece a la familia de términos en -정병 (como 취준정병, la versión de la búsqueda de empleo) con que los jóvenes bautizan su propio malestar con humor negro — aquí, la obsesión por el físico en un día a día de filtros y vídeos cortos.", "vi": "외모 (ngoại hình) + 정병, cách nói tắt thô của 정신병 (bệnh tâm thần). Tăng từ 2024 và lan mạnh sau 2025; thuộc nhóm từ -정병 (như 취준정병 bản xin việc) mà người trẻ tự đặt tên cho nỗi khổ của mình bằng kiểu hài đen — ở đây là ám ảnh ngoại hình giữa đời sống đầy filter và video ngắn.", "de": "외모 (Aussehen) + 정병, eine derbe Kurzform von 정신병 (Geisteskrankheit). Ab 2024 im Aufwind, nach 2025 explosionsartig verbreitet; gehört zur -정병-Familie (etwa 취준정병 für die Jobsuche), mit der junge Leute ihrem eigenen Leiden einen schwarzhumorigen Namen geben — hier der Aussehensdruck eines Alltags voller Filter und Kurzvideos."}'::jsonb,
 '자기 얘기를 할 때 자조적으로 쓴다. 남을 두고 「쟤 외모정병이야」라고 하면 정신질환을 놀리는 말이 되어 상처를 준다 — 실제 정신질환을 가리키는 진단명이 아니며, 「정병」 자체가 환자 비하로 쓰이던 말이라 조심해야 한다.',
 '{"en": "Used self-deprecatingly about oneself. Aimed at someone else (\"she''s got 외모정병\") it turns into mockery of mental illness and stings — it is not a diagnosis, and 정병 itself has a history as a slur against patients, so tread carefully.", "ja": "自分のことを自嘲的に言うときに使う。他人に向けて「あの子は외모정병」と言うと精神疾患を茶化す言葉になり傷つける。診断名ではなく、「정병」自体が患者への蔑称として使われてきた語なので注意。", "es": "Se usa para hablar de uno mismo con autoironía. Dirigido a otra persona («esa tiene 외모정병») se convierte en burla de la enfermedad mental y hiere: no es un diagnóstico y 정병 arrastra un uso despectivo hacia los pacientes.", "vi": "Dùng để tự giễu bản thân. Nhắm vào người khác (\"nhỏ đó bị 외모정병\") thì thành trò cười trên bệnh tâm thần và gây tổn thương — đây không phải chẩn đoán, và bản thân 정병 vốn từng là từ miệt thị người bệnh.", "de": "Wird selbstironisch über sich selbst gesagt. Auf andere gemünzt („die hat 외모정병“) wird daraus Spott über psychische Erkrankung und verletzt — es ist keine Diagnose, und 정병 selbst hat eine Geschichte als Schimpfwort gegen Betroffene."}'::jsonb,
 'Oemo Jeongbyeong',
 '[{"type": "명사", "definition": "외모에 대한 불만과 집착이 불안·강박 수준까지 간 상태를 스스로 우스개처럼 부르는 말. 병명이 아니라 자조적 과장이다.", "definition_i18n": {"en": "A jokey self-label for when dissatisfaction and fixation with one''s looks reaches the level of anxiety or compulsion. Not a medical term — deliberate self-deprecating hyperbole.", "ja": "外見への不満と執着が不安・強迫のレベルに達した状態を自分で冗談めかして呼ぶ語。病名ではなく自嘲的な誇張。", "es": "Etiqueta jocosa que uno se pone cuando la insatisfacción y la fijación con el propio aspecto llegan al nivel de ansiedad o compulsión. No es un término médico, sino hipérbole autoirónica.", "vi": "Cách tự gắn nhãn đùa khi sự bất mãn và ám ảnh về ngoại hình lên tới mức lo âu hay cưỡng chế. Không phải thuật ngữ y khoa mà là lối nói phóng đại tự giễu.", "de": "Ein scherzhaftes Selbstetikett, wenn Unzufriedenheit und Fixierung auf das eigene Aussehen Angst- oder Zwangsniveau erreichen. Kein medizinischer Begriff, sondern selbstironische Übertreibung."}, "examples": [{"kor": "거울 앞에서 30분째야… 나 진짜 외모정병인가 봐.", "eng": "Half an hour in front of the mirror… I think my looks anxiety is out of control.", "ja": "鏡の前でもう30分…私、本気で외모정병かも。", "es": "Media hora frente al espejo… creo que mi obsesión con mi cara ya es 외모정병.", "vi": "Đứng trước gương nửa tiếng rồi… chắc mình bị 외모정병 thật.", "de": "Seit einer halben Stunde vor dem Spiegel … ich glaube, mein 외모정병 ist real."}]}]'::jsonb,
 array['현타'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Looks anxiety (self-mocking)"}, {"lang": "🇯🇵 JA", "text": "外見強迫の自嘲語"}, {"lang": "🇨🇳 ZH", "text": "外貌焦虑（自嘲）"}, {"lang": "🇻🇳 VI", "text": "Ám ảnh ngoại hình (tự giễu)"}, {"lang": "🇪🇸 ES", "text": "Obsesión con el físico (autoirónico)"}, {"lang": "🇩🇪 DE", "text": "Aussehens-Zwang (selbstironisch)"}]'::jsonb),
('424', '야르바이트', 'new-slang', '조건 좋고 편한 꿀알바', '[야르바이트]',
 '{"en": "A part-time job so good it feels like a win", "ja": "条件がよくて楽な当たりバイト", "es": "Un curro a tiempo parcial que toca como premio", "vi": "Việc làm thêm ngon lành, dễ thở", "de": "Ein Nebenjob, der sich wie ein Glückstreffer anfühlt"}'::jsonb,
 '감탄사 「야르」(기분 좋을 때 외치는 말)와 「아르바이트」를 합친 말장난. 아르바이트의 「아르」 자리에 「야르」를 끼워 넣어, 걸린 것만으로 「야르!」가 나오는 알바라는 뜻을 만든다.',
 '{"en": "A pun on 아르바이트 (part-time job) with 야르 — the shout you let out when something goes your way — swapped into the 아르 slot, so the word itself says \"a job worth cheering about\".", "ja": "感嘆詞「야르」(うれしいときの掛け声)と「아르바이트(アルバイト)」を掛けた言葉遊び。아르の部分を야르に差し替えることで、受かっただけで「ヤル!」と叫べるバイトという意味になる。", "es": "Juego de palabras con 아르바이트 (trabajo a tiempo parcial) metiendo 야르 —el grito de alegría cuando algo sale bien— en el lugar de 아르, de modo que la palabra ya dice «un curro para celebrar».", "vi": "Chơi chữ từ 아르바이트 (việc làm thêm), thay 아르 bằng 야르 — tiếng reo khi gặp chuyện vui — nên bản thân từ đã nói \"việc đáng ăn mừng\".", "de": "Ein Wortspiel mit 아르바이트 (Nebenjob): An die Stelle von 아르 tritt 야르, der Freudenruf — das Wort sagt also schon „ein Job zum Jubeln“."}'::jsonb,
 '급여·근무 분위기·업무 강도가 두루 만족스러운 알바를 가리킨다. 자기가 구한 알바를 자랑할 때, 또는 친구 알바 조건을 듣고 부러워할 때 쓴다. 반대말은 딱히 굳어진 게 없다.',
 '{"en": "Describes a part-time job that is good across the board — pay, atmosphere and workload. Said when bragging about the one you landed, or enviously about a friend''s. No settled opposite exists.", "ja": "給与・職場の雰囲気・業務の負担がどれも満足なバイトを指す。自分が受かったバイトを自慢するときや、友達の条件を聞いてうらやましがるときに使う。定着した反対語はない。", "es": "Se refiere a un empleo parcial bueno en todo: sueldo, ambiente y carga. Se dice al presumir del que has conseguido o con envidia del de un amigo. No tiene antónimo asentado.", "vi": "Chỉ công việc làm thêm ngon mọi mặt: lương, không khí, cường độ. Dùng khi khoe việc mình xin được hoặc ganh tị với việc của bạn. Chưa có từ trái nghĩa cố định.", "de": "Meint einen Nebenjob, der rundum stimmt — Bezahlung, Stimmung, Arbeitspensum. Man sagt es beim Angeben über den eigenen oder neidisch über den eines Freundes. Ein festes Gegenwort gibt es nicht."}'::jsonb,
 'Yareubaiteu',
 '[{"type": "명사", "definition": "시급도 좋고 분위기도 편하고 일도 힘들지 않은, 이른바 「꿀알바」. 감탄사 「야르」가 절로 나올 만큼 잘 걸린 아르바이트라는 뜻이다.", "definition_i18n": {"en": "The so-called honey job: decent pay, easy atmosphere, light work. Literally, a part-time gig lucky enough to make you shout 야르.", "ja": "時給もよく雰囲気も楽で仕事もきつくない、いわゆる「おいしいバイト」。感嘆詞「야르」が自然に出るほど当たりのバイトという意味。", "es": "El llamado curro dulce: buena paga, ambiente relajado, trabajo ligero. Literalmente, un empleo tan afortunado que te hace gritar 야르.", "vi": "Cái gọi là việc ngọt: lương ổn, không khí thoải mái, việc nhẹ. Nghĩa đen là việc làm thêm may đến mức bật ra tiếng 야르.", "de": "Der sprichwörtliche Honigjob: ordentliche Bezahlung, entspannte Stimmung, leichte Arbeit. Wörtlich ein Nebenjob, bei dem einem 야르 herausrutscht."}, "examples": [{"kor": "카페 알바 붙었는데 사장님도 좋고 손님도 없어. 완전 야르바이트야.", "eng": "Got the café job — nice boss, no customers. Total 야르바이트 (jackpot gig).", "ja": "カフェのバイト受かったんだけど店長もいい人で客も来ない。完全に야르바이트。", "es": "Me cogieron en la cafetería: jefe majo y sin clientes. Un 야르바이트 en toda regla.", "vi": "Đậu việc ở quán cà phê, chủ dễ thương mà khách chẳng có. Đúng chuẩn 야르바이트.", "de": "Habe den Café-Job — netter Chef, keine Kundschaft. Ein astreiner 야르바이트."}]}]'::jsonb,
 array['야르','개꿀'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Jackpot part-time job"}, {"lang": "🇯🇵 JA", "text": "当たりバイト"}, {"lang": "🇨🇳 ZH", "text": "神仙兼职"}, {"lang": "🇻🇳 VI", "text": "Việc làm thêm ngon"}, {"lang": "🇪🇸 ES", "text": "Curro de premio"}, {"lang": "🇩🇪 DE", "text": "Glückstreffer-Nebenjob"}]'::jsonb),
('425', '진지충', 'slang', '[비하 표현] 매사 진지하게 받아 분위기 깨는 사람을 벌레에 빗대 낮잡는 말', '[진지충]',
 '{"en": "[derogatory] Bug-word for someone who takes every joke seriously", "ja": "[蔑称] 何でも真に受けて場を白けさせる人を虫に例えて見下す語", "es": "[despectivo] Palabra-bicho para quien se toma en serio cada broma", "vi": "[miệt thị] Từ ví như sâu bọ, chỉ người cái gì cũng nghiêm túc làm cụt hứng", "de": "[abwertend] Insekten-Wort für jemanden, der jeden Witz ernst nimmt"}'::jsonb,
 '「진지」에 비하 접미사 「-충(蟲, 벌레)」을 붙인 말. 2010년대 중반 온라인 커뮤니티에서 「한남충」·「맘충」처럼 사람을 벌레에 빗대는 -충 조어가 쏟아질 때 함께 굳었다. 접미사 자체가 상대를 사람 아래로 내려놓는 장치라 뜻과 무관하게 공격적이다.',
 '{"en": "진지 (earnest) plus the derogatory suffix -충 (蟲, insect). It set in during the mid-2010s wave of online -충 coinages that likened people to vermin (한남충, 맘충). The suffix itself is a device for placing someone beneath human, so the word is aggressive regardless of the sense.", "ja": "「진지(真剣)」に蔑称接尾辞「-충(蟲、虫)」を付けた語。2010年代半ば、한남충・맘충のように人を虫に例える -충 造語がネットに溢れた時期に定着した。接尾辞自体が相手を人以下に置く装置なので、意味に関係なく攻撃的。", "es": "진지 (serio) más el sufijo despectivo -충 (蟲, insecto). Cuajó a mediados de los 2010, en la oleada de términos en -충 que comparaban personas con bichos (한남충, 맘충). El sufijo ya es un mecanismo para rebajar a alguien por debajo de lo humano, así que la palabra es agresiva de por sí.", "vi": "진지 (nghiêm túc) cộng hậu tố miệt thị -충 (蟲, côn trùng). Nó định hình giữa thập niên 2010, thời làn sóng từ -충 trên mạng ví người như sâu bọ (한남충, 맘충). Bản thân hậu tố là cách hạ người khác xuống dưới mức con người, nên từ này hung hăng bất kể nghĩa.", "de": "진지 (ernst) plus das abwertende Suffix -충 (蟲, Insekt). Es setzte sich Mitte der 2010er durch, als das Netz von -충-Wörtern überschwemmt wurde, die Menschen mit Ungeziefer gleichsetzten (한남충, 맘충). Das Suffix allein stellt jemanden unter den Menschen — das Wort ist also unabhängig vom Sinn aggressiv."}'::jsonb,
 '쓰면 안 되는 말이고, 들었을 때 무슨 뜻인지 알아두는 용도로 싣는다. -충이 붙는 순간 놀림이 아니라 인신공격이 되며, 진지한 지적을 입막음하는 데 쓰이기도 한다. 비슷한 뜻으로 「씹선비」가 있고, 벌레에 빗대지 않는 순한 말로는 「진지스칸」이 있다.',
 '{"en": "A word to recognise, not to use. The moment -충 is attached it stops being teasing and becomes a personal attack, and it is often used to shut down a serious point. 씹선비 is close in meaning; 진지스칸 makes the same joke without the vermin comparison.", "ja": "使ってはいけない語で、聞いたときに意味が分かるように載せている。-충が付いた瞬間にからかいではなく人格攻撃になり、真剣な指摘を封じるのにも使われる。近い語に「씹선비」、虫に例えない穏やかな言い方に「진지스칸」がある。", "es": "Palabra para reconocer, no para usar. En cuanto se añade -충 deja de ser burla y pasa a ser ataque personal, y a menudo sirve para callar una objeción seria. 씹선비 es cercano; 진지스칸 hace la misma broma sin comparar con bichos.", "vi": "Từ để nhận biết, không phải để dùng. Khi gắn -충 thì hết là trêu mà thành công kích cá nhân, và hay bị dùng để dập tắt góp ý nghiêm túc. 씹선비 gần nghĩa; 진지스칸 đùa cùng ý mà không ví với sâu bọ.", "de": "Ein Wort zum Erkennen, nicht zum Benutzen. Sobald -충 dranhängt, ist es kein Necken mehr, sondern ein persönlicher Angriff — oft dient es dazu, einen ernsten Einwand abzuwürgen. 씹선비 liegt nah; 진지스칸 macht denselben Witz ohne Ungeziefervergleich."}'::jsonb,
 'Jinjichung',
 '[{"type": "명사", "definition": "농담이나 가벼운 대화에 매번 정색하고 진지하게 반응해 분위기를 깨는 사람을 벌레에 빗대 낮잡아 이르는 말. 상대를 벌레 취급하는 심한 비하 표현이다.", "definition_i18n": {"en": "A demeaning term, likening the person to an insect, for someone who answers every joke or light chat with a straight face and kills the mood. Calling a person vermin makes it a harsh slur.", "ja": "冗談や軽い会話にいちいち真顔で真剣に反応して場を白けさせる人を、虫に例えて見下して呼ぶ語。相手を虫扱いする強い蔑称。", "es": "Término degradante, que compara a la persona con un insecto, para quien responde a cada broma con cara seria y mata el ambiente. Llamar bicho a alguien lo convierte en un insulto duro.", "vi": "Từ hạ nhục, ví người ta như sâu bọ, chỉ kẻ đáp lại mọi câu đùa bằng vẻ mặt nghiêm túc và làm cụt hứng. Gọi người là sâu bọ khiến đây thành lời miệt thị nặng.", "de": "Ein herabwürdigender Ausdruck, der die Person mit einem Insekt gleichsetzt, für jemanden, der auf jeden Scherz bierernst reagiert und die Stimmung killt. Jemanden Ungeziefer zu nennen macht es zur harten Beleidigung."}, "examples": [{"kor": "장난인데 왜 정색해, 진지충이야?", "eng": "It was a joke — why so serious? Don''t be a 진지충 (buzzkill bug).", "ja": "冗談なのに何で真顔なの、진지충?", "es": "Era broma, ¿por qué te pones serio? Menudo 진지충.", "vi": "Đùa thôi mà sao nghiêm thế, 진지충 à?", "de": "War ein Witz — warum so ernst, du 진지충?"}]}]'::jsonb,
 array['진지스칸','씹선비'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Buzzkill (harsh slur)"}, {"lang": "🇯🇵 JA", "text": "真面目虫(強い蔑称)"}, {"lang": "🇨🇳 ZH", "text": "认真虫（贬义）"}, {"lang": "🇻🇳 VI", "text": "Sâu nghiêm túc (miệt thị)"}, {"lang": "🇪🇸 ES", "text": "Aguafiestas (insulto)"}, {"lang": "🇩🇪 DE", "text": "Ernst-Insekt (Beleidigung)"}]'::jsonb),
('426', '나일리지', 'new-slang', '나이를 앞세워 대접받으려는 태도', '[나일리지]',
 '{"en": "Cashing in your age for special treatment", "ja": "年齢を盾に特別扱いを求める態度", "es": "Cobrar puntos por la edad para exigir trato especial", "vi": "Lấy tuổi ra đòi được ưu đãi", "de": "Sein Alter als Bonuspunkte für Sonderbehandlung einlösen"}'::jsonb,
 '「나이」와 적립 점수를 뜻하는 「마일리지(mileage)」를 합친 말. 나이를 쌓을수록 포인트가 적립돼 대우로 바꿔 쓸 수 있다는 듯한 태도를 비꼰다. 2018년 무렵 언론 신조어 사전에 실릴 만큼 자리 잡았고 「꼰대」와 짝으로 다뤄진다.',
 '{"en": "나이 (age) blended with 마일리지 (mileage points), mocking the attitude that years accumulate like reward points you can redeem for deference. It was settled enough to appear in newspaper neologism columns by around 2018, and is usually discussed alongside 꼰대.", "ja": "「나이(年齢)」とポイントを意味する「마일리지(マイレージ)」の合成語。年を重ねるほどポイントが貯まり待遇に交換できるかのような態度を皮肉る。2018年頃には新聞の新語コラムに載るほど定着し、「꼰대」とセットで語られる。", "es": "나이 (edad) fusionado con 마일리지 (puntos de fidelidad), y se burla de quien actúa como si los años se acumularan en puntos canjeables por deferencia. Hacia 2018 ya aparecía en los diccionarios de neologismos de la prensa, y suele tratarse junto a 꼰대.", "vi": "나이 (tuổi) ghép với 마일리지 (điểm tích lũy), giễu thái độ coi như càng nhiều tuổi càng tích điểm rồi đổi lấy sự nể trọng. Khoảng 2018 nó đã đủ phổ biến để lên mục từ mới của báo, và thường được nhắc cùng 꼰대.", "de": "나이 (Alter) verschmolzen mit 마일리지 (Bonusmeilen) — verspottet die Haltung, Jahre sammelten sich wie Punkte, die man gegen Respekt eintauschen kann. Um 2018 war es etabliert genug für Neologismus-Kolumnen der Presse und wird meist zusammen mit 꼰대 behandelt."}'::jsonb,
 '주로 젊은 세대가 손윗사람의 태도를 비꼴 때 쓴다. 「나일리지 쓴다」처럼 동사와 함께 쓰는 게 자연스럽다. 본인 앞에서 쓰면 정면으로 비난하는 말이 되니 뒤에서 하는 말에 가깝다.',
 '{"en": "Mostly used by younger people to mock how an older person behaves. It sits naturally with a verb, as in 나일리지 쓴다 (\"spending their age points\"). Said to someone''s face it is a direct accusation, so it lives mostly behind their back.", "ja": "主に若い世代が目上の態度を皮肉るときに使う。「나일리지 쓴다(年齢ポイントを使う)」のように動詞と組むのが自然。本人の前で言うと正面からの非難になるので、陰で言う語に近い。", "es": "Lo usan sobre todo los jóvenes para burlarse de cómo se comporta alguien mayor. Encaja con verbo: 나일리지 쓴다, «gastar los puntos de edad». Dicho a la cara es una acusación directa, así que suele decirse por detrás.", "vi": "Chủ yếu người trẻ dùng để giễu cách hành xử của người lớn tuổi. Đi với động từ thì tự nhiên: 나일리지 쓴다 (\"xài điểm tuổi\"). Nói thẳng mặt thành lời tố cáo, nên thường nói sau lưng.", "de": "Meist von Jüngeren benutzt, um das Auftreten Älterer zu verspotten. Natürlich mit Verb: 나일리지 쓴다 („seine Alterspunkte ausgeben“). Ins Gesicht gesagt ist es ein direkter Vorwurf, es fällt also eher hinter dem Rücken."}'::jsonb,
 'Naillage',
 '[{"type": "명사", "definition": "나이가 많다는 것만으로 우대와 배려를 당연하게 여기는 태도. 나이를 마일리지처럼 적립해 두었다가 꺼내 쓴다는 비유다.", "definition_i18n": {"en": "The attitude of treating deference and privilege as owed simply for being older — as if age were mileage banked up and then spent.", "ja": "年上であるというだけで優遇と配慮を当然と思う態度。年齢をマイレージのように貯めておいて引き出すという比喩。", "es": "La actitud de dar por sentado el trato preferente solo por tener más años, como si la edad fuera millas acumuladas que luego se gastan.", "vi": "Thái độ coi việc được ưu ái là đương nhiên chỉ vì nhiều tuổi hơn — như thể tuổi là điểm tích rồi đem ra tiêu.", "de": "Die Haltung, Vorrang und Rücksicht allein wegen des höheren Alters für selbstverständlich zu halten — als wären Jahre angesparte Meilen, die man ausgibt."}, "examples": [{"kor": "또 나일리지 쓰신다, 나이가 벼슬도 아니고.", "eng": "There goes the age card again — being older isn''t a rank.", "ja": "また나일리지を使ってるよ、年齢は役職じゃないのに。", "es": "Otra vez sacando la carta de la edad, que ser mayor no es un cargo.", "vi": "Lại lôi tuổi ra rồi, lớn tuổi có phải chức vụ đâu.", "de": "Schon wieder die Alterskarte — älter zu sein ist kein Rang."}]}]'::jsonb,
 array['틀딱'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Age entitlement"}, {"lang": "🇯🇵 JA", "text": "年齢マイレージ"}, {"lang": "🇨🇳 ZH", "text": "倚老卖老"}, {"lang": "🇻🇳 VI", "text": "Ỷ tuổi đòi ưu đãi"}, {"lang": "🇪🇸 ES", "text": "Privilegio por edad"}, {"lang": "🇩🇪 DE", "text": "Alters-Anspruchsdenken"}]'::jsonb),
('427', '틀딱', 'slang', '[차별적 비하 표현] 노인을 틀니 소리에 빗대 낮잡는 노인혐오 표현', '[틀딱]',
 '{"en": "[discriminatory slur] Anti-old slur mocking the clack of dentures", "ja": "[差別的蔑称] 入れ歯の音に例えて高齢者を見下す老人差別語", "es": "[insulto discriminatorio] Insulto edadista que imita el chasquido de la dentadura", "vi": "[miệt thị phân biệt] Từ kỳ thị người già, nhại tiếng răng giả lập cập", "de": "[diskriminierender Slur] Altersfeindliches Schimpfwort nach dem Klappern des Gebisses"}'::jsonb,
 '「틀니」와 딱딱거리는 소리를 나타내는 「딱」을 합친 말. 노인이 틀니를 부딪치며 말한다는 조롱에서 나왔고, 2010년대 중반 온라인 커뮤니티의 세대 갈등 속에서 「한남충」·「맘충」류의 집단 비하어와 함께 퍼졌다. 신체적 특징을 잡아 한 세대 전체를 조롱하는 구조라는 점에서 명백한 차별 표현이다.',
 '{"en": "틀니 (dentures) plus 딱, the clacking sound. It comes from mocking older people as talking through rattling false teeth, and spread through mid-2010s online generational conflict alongside group slurs like 한남충 and 맘충. Seizing on a physical trait to mock an entire generation makes it plainly discriminatory.", "ja": "「틀니(入れ歯)」とカチカチという音の「딱」を合わせた語。高齢者が入れ歯を鳴らして話すという嘲りから生まれ、2010年代半ばのネット上の世代対立の中で한남충・맘충のような集団蔑称と共に広まった。身体的特徴を捉えて世代全体を嘲る構造で、明白な差別表現。", "es": "틀니 (dentadura postiza) más 딱, el chasquido. Nace de burlarse de los mayores como si hablaran haciendo sonar la dentadura, y se extendió en el conflicto generacional online de mediados de los 2010 junto a insultos de grupo como 한남충 y 맘충. Usar un rasgo físico para burlarse de toda una generación lo hace claramente discriminatorio.", "vi": "틀니 (răng giả) cộng 딱, tiếng lập cập. Xuất phát từ việc chế nhạo người già nói mà răng giả kêu, lan rộng trong xung đột thế hệ trên mạng giữa thập niên 2010 cùng các từ miệt thị nhóm như 한남충, 맘충. Lấy đặc điểm cơ thể ra giễu cả một thế hệ khiến nó rõ ràng là kỳ thị.", "de": "틀니 (Gebiss) plus 딱, das Klappergeräusch. Es entstand aus dem Spott, Ältere sprächen mit klapperndem Gebiss, und verbreitete sich im Generationenkonflikt des Netzes Mitte der 2010er neben Gruppenschimpfwörtern wie 한남충 und 맘충. Ein körperliches Merkmal zu greifen, um eine ganze Generation zu verhöhnen, macht es eindeutig diskriminierend."}'::jsonb,
 '절대 쓰지 말 것. 뜻을 알아두는 용도로만 싣는다. 노인이라는 집단 전체를 겨냥한 혐오 표현이라 농담으로도 통하지 않고, 공개된 자리나 온라인에서 쓰면 심각한 문제가 된다. 나이를 앞세우는 태도만 비꼬고 싶다면 「나일리지」처럼 사람 자체를 비하하지 않는 말을 쓴다.',
 '{"en": "Never use this. It is listed only so you recognise it. As hate speech aimed at an entire age group it does not pass as a joke, and using it in public or online causes real trouble. If you only want to criticise age-based entitlement, use a word like 나일리지 that targets the behaviour rather than the person.", "ja": "絶対に使わないこと。意味を知るためだけに載せている。高齢者という集団全体に向けた憎悪表現なので冗談としても通らず、公の場やネットで使えば深刻な問題になる。年齢を振りかざす態度だけを批判したいなら、人自体を貶めない「나일리지」のような語を使う。", "es": "No lo uses nunca. Se incluye solo para que lo reconozcas. Es discurso de odio contra todo un grupo de edad, no cuela como broma, y usarlo en público o en internet acarrea problemas serios. Si solo quieres criticar el privilegio por edad, usa una palabra como 나일리지, que apunta a la conducta y no a la persona.", "vi": "Tuyệt đối đừng dùng. Đưa vào chỉ để bạn nhận ra nó. Đây là lời thù ghét nhắm vào cả một nhóm tuổi, đùa cũng không lọt, và dùng nơi công cộng hay trên mạng sẽ gây rắc rối thật sự. Nếu chỉ muốn phê phán thói ỷ tuổi, hãy dùng từ như 나일리지 vốn nhắm vào hành vi chứ không hạ nhục con người.", "de": "Niemals verwenden. Es steht hier nur zum Wiedererkennen. Als Hassrede gegen eine ganze Altersgruppe geht es auch als Witz nicht durch, und öffentlich oder online benutzt zieht es ernsten Ärger nach sich. Wer nur Altersanmaßung kritisieren will, nimmt ein Wort wie 나일리지, das auf das Verhalten zielt statt auf die Person."}'::jsonb,
 'Teulttak',
 '[{"type": "명사", "definition": "노인을 낮잡아 이르는 심한 비하 표현. 틀니가 딱딱거린다는 조롱에서 온 말로, 나이 든 사람 전체를 겨냥한 혐오 표현이다.", "definition_i18n": {"en": "A severe slur for old people, from mocking the clack of dentures — hate speech aimed at the elderly as a group.", "ja": "高齢者を見下す強い蔑称。入れ歯がカチカチ鳴るという嘲りから来た語で、年配者全体に向けた憎悪表現。", "es": "Insulto grave contra los mayores, nacido de burlarse del chasquido de la dentadura; discurso de odio contra los ancianos como grupo.", "vi": "Từ miệt thị nặng nhắm vào người già, từ chỗ chế tiếng răng giả lập cập — là lời thù ghét nhắm vào cả nhóm người cao tuổi.", "de": "Ein schweres Schimpfwort für alte Menschen, aus dem Spott über klapperndes Gebiss — Hassrede gegen Ältere als Gruppe."}, "examples": [{"kor": "댓글에 틀딱이라고 쓴 사람 신고당했대.", "eng": "The person who wrote 틀딱 in the comments got reported.", "ja": "コメントに틀딱と書いた人、通報されたって。", "es": "Al que escribió 틀딱 en los comentarios lo denunciaron.", "vi": "Người viết 틀딱 trong bình luận bị báo cáo rồi.", "de": "Wer in den Kommentaren 틀딱 geschrieben hat, wurde gemeldet."}]}]'::jsonb,
 array['나일리지'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Anti-elderly slur"}, {"lang": "🇯🇵 JA", "text": "高齢者への蔑称"}, {"lang": "🇨🇳 ZH", "text": "对老年人的蔑称"}, {"lang": "🇻🇳 VI", "text": "Từ miệt thị người già"}, {"lang": "🇪🇸 ES", "text": "Insulto edadista"}, {"lang": "🇩🇪 DE", "text": "Slur gegen Alte"}]'::jsonb),
('428', '풀청', 'kpop', '곡을 처음부터 끝까지 건드리지 않고 듣는 스밍 방식', '[풀청]',
 '{"en": "Streaming a track start to finish without touching it", "ja": "曲を最初から最後まで触らずに聴くストリーミング法", "es": "Escuchar el tema entero sin tocar nada, para que cuente", "vi": "Nghe trọn bài từ đầu đến cuối, không đụng vào", "de": "Einen Track von vorn bis hinten durchlaufen lassen, ohne einzugreifen"}'::jsonb,
 '영어 「full」과 「청취(聽取)」의 「청」을 붙인 말. 음원 사이트가 재생을 실적으로 인정하는 조건에 맞추려고 팬덤이 만든 스밍(스트리밍) 용어로, 「총공」·「스밍」과 같은 차트 화력 문화에서 나왔다.',
 '{"en": "English full plus 청 from 청취 (listening). A fandom streaming term coined to satisfy the conditions under which music services count a play, born out of the same chart-pushing culture as 총공 and 스밍.", "ja": "英語の full と「청취(聴取)」の「청」を付けた語。音源サイトが再生を実績として認める条件に合わせるためファンダムが作ったストリーミング用語で、「총공」「스밍」と同じチャート火力文化から生まれた。", "es": "El inglés full más 청, de 청취 (escucha). Término de streaming acuñado por los fandoms para cumplir las condiciones con que las plataformas cuentan una reproducción; nace de la misma cultura de empuje en listas que 총공 y 스밍.", "vi": "Từ tiếng Anh full cộng 청 trong 청취 (nghe). Thuật ngữ stream do fandom đặt ra để khớp điều kiện mà các nền tảng tính một lượt nghe, sinh ra từ cùng văn hóa đẩy chart với 총공 và 스밍.", "de": "Englisch full plus 청 aus 청취 (Hören). Ein Fandom-Streaming-Begriff, geprägt, um die Bedingungen zu erfüllen, unter denen Dienste einen Play zählen — aus derselben Chart-Push-Kultur wie 총공 und 스밍."}'::jsonb,
 '팬덤 안에서 쓰는 말이다. 「풀청해 주세요」처럼 스밍 독려 글에 자주 나온다. 재생바를 끌거나 넘기면 실적으로 안 잡히니 손대지 말라는 뜻이 핵심이다. 비슷한 말로 「완청」이 있다.',
 '{"en": "In-fandom vocabulary; it shows up constantly in streaming-drive posts as 풀청해 주세요 (\"please full-listen\"). The point is that dragging the bar or skipping stops the play from counting, so hands off. 완청 is a close equivalent.", "ja": "ファンダム内で使う語。「풀청해 주세요(フル再生してください)」のようにストリーミング呼びかけの投稿に頻出する。再生バーをドラッグしたり飛ばしたりすると実績に数えられないので触るな、というのが要点。近い語に「완청」。", "es": "Vocabulario interno del fandom; aparece sin parar en las convocatorias de streaming como 풀청해 주세요 («escuchadlo entero»). La clave es que arrastrar la barra o saltar impide que cuente, así que no se toca. 완청 es equivalente.", "vi": "Từ dùng trong fandom; xuất hiện liên tục ở các bài kêu gọi stream dạng 풀청해 주세요 (\"nghe trọn giúp nhé\"). Điểm mấu chốt là kéo thanh phát hay tua thì không được tính, nên đừng đụng vào. 완청 là từ tương đương.", "de": "Fandom-Vokabular; taucht ständig in Streaming-Aufrufen auf, etwa 풀청해 주세요 („bitte komplett hören“). Der Kern: Wer die Leiste zieht oder skippt, dessen Play zählt nicht — also Finger weg. 완청 ist gleichbedeutend."}'::jsonb,
 'Pulcheong',
 '[{"type": "명사", "definition": "곡을 0초부터 다음 곡으로 넘어갈 때까지 재생바를 건드리지 않고 끝까지 듣는 것. 스트리밍이 실적으로 인정받게 하려는 팬덤의 듣기 방식이다.", "definition_i18n": {"en": "Playing a song from 0:00 until it rolls into the next one without touching the progress bar — the fandom listening method that makes a stream count.", "ja": "曲を0秒から次の曲に移るまで再生バーを触らずに最後まで聴くこと。ストリーミングが実績として認められるようにするファンダムの聴き方。", "es": "Reproducir una canción desde el 0:00 hasta que pasa a la siguiente sin tocar la barra: el método de escucha del fandom para que la reproducción cuente.", "vi": "Phát bài từ giây 0 cho tới khi tự chuyển sang bài kế mà không đụng thanh tiến trình — cách nghe của fandom để lượt stream được tính.", "de": "Ein Lied von 0:00 laufen lassen, bis es ins nächste übergeht, ohne die Leiste anzufassen — die Hörmethode des Fandoms, damit der Stream zählt."}, "examples": [{"kor": "오늘 컴백이라 다들 풀청 부탁드려요!", "eng": "Comeback day — everyone please 풀청 (full-listen, no skipping)!", "ja": "今日カムバックなのでみんな풀청お願いします!", "es": "Hoy es el comeback, ¡escuchadlo entero sin saltar, porfa!", "vi": "Hôm nay comeback, mọi người nghe trọn bài giúp nhé!", "de": "Heute ist Comeback — bitte alle komplett durchhören!"}]}]'::jsonb,
 array[]::text[], array['완청'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Full uninterrupted listen"}, {"lang": "🇯🇵 JA", "text": "フル再生"}, {"lang": "🇨🇳 ZH", "text": "完整播放"}, {"lang": "🇻🇳 VI", "text": "Nghe trọn bài"}, {"lang": "🇪🇸 ES", "text": "Escucha completa"}, {"lang": "🇩🇪 DE", "text": "Komplettes Durchhören"}]'::jsonb),
('429', '찍먹', 'daily', '소스에 찍어 먹는 쪽 / 살짝만 맛보다', '[찡먹]',
 '{"en": "Team dip-it — or to try just a taste of something", "ja": "つけて食べる派 — または少しだけかじってみること", "es": "Equipo mojar — o probar algo solo un poquito", "vi": "Phe chấm — hoặc thử qua một chút cho biết", "de": "Team Eintunken — oder etwas nur mal antesten"}'::jsonb,
 '「찍어 먹다」를 줄인 말. 탕수육 소스를 부어 먹느냐(부먹) 찍어 먹느냐(찍먹)를 두고 벌어진 온라인 논쟁에서 굳었고, 편을 나누는 농담 소재로 오래 살아남았다. 여기서 「깊이 들어가지 않고 겉만 살짝」이라는 비유가 갈라져 나와, 음식과 무관한 일에도 쓰이게 됐다.',
 '{"en": "Short for 찍어 먹다, to dip and eat. It hardened in the long-running online argument over sweet-and-sour pork — pour the sauce on (부먹) or dip (찍먹) — and survived as a favourite way to split people into camps. From there a figurative sense branched off: barely scratching the surface, which now applies to things that have nothing to do with food.", "ja": "「찍어 먹다(つけて食べる)」の略。酢豚のソースをかけるか(부먹)つけるか(찍먹)を巡るネット論争で定着し、人を二派に分ける定番のネタとして生き残った。そこから「深入りせず表面だけ軽く」という比喩が枝分かれし、食べ物と無関係なことにも使われるようになった。", "es": "Abreviatura de 찍어 먹다, mojar y comer. Cuajó en la eterna discusión online sobre el cerdo agridulce —¿verter la salsa (부먹) o mojar (찍먹)?— y sobrevivió como forma favorita de dividir a la gente en bandos. De ahí se desgajó un sentido figurado: rozar la superficie, que hoy se aplica a cosas que nada tienen que ver con la comida.", "vi": "Rút gọn của 찍어 먹다, chấm rồi ăn. Nó định hình trong cuộc tranh cãi trường kỳ trên mạng về món heo chua ngọt — chan sốt (부먹) hay chấm (찍먹) — và sống dai như cách chia phe quen thuộc. Từ đó tách ra nghĩa bóng: chỉ chạm bề mặt, nay dùng cho cả những việc chẳng liên quan đồ ăn.", "de": "Kurz für 찍어 먹다, eintunken und essen. Es verfestigte sich im endlosen Netzstreit über süß-saures Schweinefleisch — Soße drübergießen (부먹) oder eintunken (찍먹) — und überlebte als beliebte Art, Leute in Lager zu teilen. Daraus zweigte eine übertragene Bedeutung ab: nur an der Oberfläche kratzen, heute auch fernab von Essen."}'::jsonb,
 '1번 뜻은 음식 앞에서 편을 물을 때(「너 부먹이야 찍먹이야?」) 쓴다. 2번 뜻은 「찍먹만 해봤어」처럼 게임·드라마·취미를 살짝만 건드려 봤다고 할 때 쓴다. 둘 다 가벼운 반말 자리에서 쓰는 말이다.',
 '{"en": "Sense 1 comes out when asking which camp someone is in over food (\"부먹 or 찍먹?\"). Sense 2 appears as 찍먹만 해봤어 — I only dabbled — about a game, a show, a hobby. Both belong to casual banmal conversation.", "ja": "1の意味は食べ物を前に派閥を聞くとき(「부먹?찍먹?」)に使う。2の意味は「찍먹만 해봤어(ちょっとかじっただけ)」のようにゲーム・ドラマ・趣味を少しだけ触ってみたと言うときに使う。どちらもタメ口の砕けた場面の語。", "es": "El sentido 1 sale al preguntar de qué bando eres ante la comida («¿부먹 o 찍먹?»). El 2 aparece como 찍먹만 해봤어, «solo lo probé por encima», sobre un juego, una serie o una afición. Ambos son de conversación informal.", "vi": "Nghĩa 1 dùng khi hỏi phe nào trước món ăn (\"부먹 hay 찍먹?\"). Nghĩa 2 xuất hiện dạng 찍먹만 해봤어 — mới thử sơ thôi — về game, phim, sở thích. Cả hai đều thuộc lối nói thân mật.", "de": "Bedeutung 1 fällt, wenn man beim Essen nach dem Lager fragt („부먹 oder 찍먹?“). Bedeutung 2 erscheint als 찍먹만 해봤어 — ich hab nur reingeschnuppert — über ein Spiel, eine Serie, ein Hobby. Beides gehört in lockere Banmal-Gespräche."}'::jsonb,
 'Jjikmeok',
 '[{"type": "명사", "definition": "탕수육 등을 소스에 찍어 먹는 방식, 또는 그렇게 먹는 사람. 소스를 부어 먹는 「부먹」과 짝을 이뤄 편을 가르는 농담거리로 쓰인다.", "definition_i18n": {"en": "Dipping food such as sweet-and-sour pork into the sauce, or the person who does. It pairs with 부먹 (pour it on) as the classic way to sort people into camps.", "ja": "酢豚などをソースにつけて食べる方式、またはそう食べる人。ソースをかける「부먹」と対になり、派閥を分けるネタとして使われる。", "es": "Mojar en la salsa comida como el cerdo agridulce, o quien lo hace así. Forma pareja con 부먹 (verterla) como manera clásica de repartir a la gente en bandos.", "vi": "Cách chấm món như heo chua ngọt vào sốt, hoặc người ăn kiểu đó. Đi cặp với 부먹 (chan sốt) như trò chia phe kinh điển.", "de": "Speisen wie süß-saures Schweinefleisch in die Soße tunken — oder die Person, die das tut. Bildet mit 부먹 (drübergießen) den Klassiker der Lagerbildung."}, "examples": [{"kor": "탕수육 시켰는데 너 부먹이야 찍먹이야?", "eng": "Ordered sweet-and-sour pork — are you 부먹 (pour) or 찍먹 (dip)?", "ja": "酢豚頼んだけど、君は부먹?찍먹?", "es": "He pedido cerdo agridulce: ¿tú eres de 부먹 o de 찍먹?", "vi": "Gọi heo chua ngọt rồi, cậu phe 부먹 hay 찍먹?", "de": "Habe süß-saures Schweinefleisch bestellt — bist du 부먹 oder 찍먹?"}]}, {"type": "명사", "definition": "무언가를 깊이 파지 않고 살짝만 맛보듯 해보는 것. 소스를 살짝 찍는 모습에서 나온 비유로, 게임·드라마·취미를 잠깐 건드려 봤다고 할 때 쓴다.", "definition_i18n": {"en": "Trying something only lightly, the way you would dip rather than dive in — used of a game, a show or a hobby you barely sampled.", "ja": "何かを深く掘らず、少しだけ味見するようにやってみること。ソースを軽くつける様子からの比喩で、ゲーム・ドラマ・趣味をちょっと触ってみたと言うときに使う。", "es": "Probar algo solo por encima, como quien moja en vez de zambullirse: se dice de un juego, una serie o una afición que apenas has catado.", "vi": "Thử một thứ gì đó rất nhẹ, kiểu chấm chứ không lao vào — nói về game, phim hay sở thích mới nếm qua.", "de": "Etwas nur leicht ausprobieren, eintunken statt eintauchen — über ein Spiel, eine Serie, ein Hobby, das man kaum angetestet hat."}, "examples": [{"kor": "그 게임? 찍먹만 해봤어, 한 시간 하고 지웠어.", "eng": "That game? I only dipped in — played an hour and deleted it.", "ja": "あのゲーム?찍먹しただけ、1時間やって消した。", "es": "¿Ese juego? Solo lo caté: una hora y lo borré.", "vi": "Game đó hả? Mới thử sơ thôi, chơi một tiếng rồi xóa.", "de": "Das Spiel? Nur angetestet — eine Stunde gespielt und gelöscht."}]}]'::jsonb,
 array['부먹'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Team dip / to dabble"}, {"lang": "🇯🇵 JA", "text": "つける派/かじる"}, {"lang": "🇨🇳 ZH", "text": "蘸酱派／浅尝"}, {"lang": "🇻🇳 VI", "text": "Phe chấm / thử sơ"}, {"lang": "🇪🇸 ES", "text": "Equipo mojar / catar"}, {"lang": "🇩🇪 DE", "text": "Team Tunken / antesten"}]'::jsonb),
('430', '부먹', 'daily', '소스를 부어 먹는 쪽', '[부먹]',
 '{"en": "Team pour-it-on", "ja": "ソースをかけて食べる派", "es": "Equipo verter la salsa", "vi": "Phe chan sốt", "de": "Team Soße-drüber"}'::jsonb,
 '「부어 먹다」를 줄인 말. 탕수육 소스를 부어 먹느냐 찍어 먹느냐를 두고 벌어진 온라인 논쟁에서 「찍먹」과 짝으로 굳었다. 실제로는 취향 차이일 뿐인데 진영을 나눠 다투는 형식 자체가 오래 사랑받아, 이후 다른 사소한 취향 대립을 부를 때의 틀이 됐다.',
 '{"en": "Short for 부어 먹다, to pour and eat. It set in as the partner of 찍먹 in the online argument over sweet-and-sour pork sauce. The split is pure preference, but the format of picking sides proved so durable that it became the template for naming other trivial taste divides.", "ja": "「부어 먹다(かけて食べる)」の略。酢豚のソースをかけるかつけるかを巡るネット論争で「찍먹」と対になって定着した。実際は好みの差にすぎないが、陣営を分けて争う形式自体が長く愛され、その後の些細な好み対立を呼ぶ枠組みになった。", "es": "Abreviatura de 부어 먹다, verter y comer. Cuajó como pareja de 찍먹 en la discusión online sobre la salsa del cerdo agridulce. Es puro gusto personal, pero el formato de elegir bando resultó tan duradero que se volvió la plantilla para bautizar otras divisiones triviales.", "vi": "Rút gọn của 부어 먹다, chan rồi ăn. Nó định hình như cặp đôi của 찍먹 trong cuộc tranh cãi trên mạng về sốt heo chua ngọt. Vốn chỉ là khác khẩu vị, nhưng lối chia phe ấy bền đến mức thành khuôn mẫu để gọi tên những cuộc chia rẽ vặt vãnh khác.", "de": "Kurz für 부어 먹다, drübergießen und essen. Es setzte sich als Gegenstück zu 찍먹 im Netzstreit über die Soße zum süß-sauren Schweinefleisch fest. Es ist reine Geschmackssache, doch das Format der Lagerwahl hielt sich so hartnäckig, dass es zur Vorlage für andere belanglose Geschmacksgräben wurde."}'::jsonb,
 '「너 부먹이야 찍먹이야?」처럼 편을 묻는 농담에 쓴다. 진지한 다툼이 아니라 친해지려고 던지는 가벼운 질문에 가깝다. 「찍먹」과 반드시 짝으로 이해해야 하는 말이다.',
 '{"en": "Used in the joking question of allegiance: \"부먹 or 찍먹?\" It is not a real fight but a light icebreaker. The word only makes sense as half of the pair with 찍먹.", "ja": "「부먹?찍먹?」のように派閥を聞く冗談で使う。本気の争いではなく、打ち解けるための軽い質問に近い。「찍먹」と必ず対で理解する語。", "es": "Se usa en la pregunta jocosa de bando: «¿부먹 o 찍먹?». No es una pelea real, sino un rompehielos ligero. Solo tiene sentido como mitad del par con 찍먹.", "vi": "Dùng trong câu hỏi phe phái đùa vui: \"부먹 hay 찍먹?\". Không phải cãi nhau thật mà là câu mở lời cho thân. Từ này chỉ có nghĩa khi hiểu cặp với 찍먹.", "de": "Kommt in der scherzhaften Lagerfrage vor: „부먹 oder 찍먹?“ Kein echter Streit, sondern ein lockerer Eisbrecher. Das Wort ergibt nur als Hälfte des Paares mit 찍먹 Sinn."}'::jsonb,
 'Bumeok',
 '[{"type": "명사", "definition": "탕수육 등에 소스를 아예 부어 먹는 방식, 또는 그렇게 먹는 사람. 소스에 찍어 먹는 「찍먹」과 짝을 이룬다.", "definition_i18n": {"en": "Pouring the sauce straight over food such as sweet-and-sour pork, or the person who eats that way. The counterpart of 찍먹 (dip it).", "ja": "酢豚などにソースをそのままかけて食べる方式、またはそう食べる人。つけて食べる「찍먹」と対をなす。", "es": "Verter la salsa directamente sobre comida como el cerdo agridulce, o quien come así. La contraparte de 찍먹 (mojar).", "vi": "Chan thẳng sốt lên món như heo chua ngọt, hoặc người ăn kiểu đó. Đối lại với 찍먹 (chấm).", "de": "Die Soße direkt über Speisen wie süß-saures Schweinefleisch gießen — oder wer so isst. Das Gegenstück zu 찍먹 (eintunken)."}, "examples": [{"kor": "난 무조건 부먹이지, 소스 다 배야 맛있어.", "eng": "I''m 부먹 all the way — it''s better once the sauce soaks in.", "ja": "俺は絶対부먹、ソースが染みてこそうまい。", "es": "Yo soy de 부먹 sin dudarlo: está mejor cuando se empapa.", "vi": "Tớ chắc chắn phe 부먹, sốt ngấm vào mới ngon.", "de": "Ich bin klar 부먹 — mit durchgezogener Soße schmeckt''s besser."}]}]'::jsonb,
 array['찍먹'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Team pour-it-on"}, {"lang": "🇯🇵 JA", "text": "かける派"}, {"lang": "🇨🇳 ZH", "text": "浇酱派"}, {"lang": "🇻🇳 VI", "text": "Phe chan sốt"}, {"lang": "🇪🇸 ES", "text": "Equipo verter"}, {"lang": "🇩🇪 DE", "text": "Team Soße-drüber"}]'::jsonb),
('431', '따라', 'daily', '따뜻한 라떼 — 카페 주문 줄임말', '[따라]',
 '{"en": "Hot latte — café order shorthand", "ja": "ホットラテ — カフェ注文の略語", "es": "Latte caliente — abreviatura para pedir en el café", "vi": "Latte nóng — tiếng lóng gọi đồ ở quán", "de": "Heißer Latte — Café-Bestellkürzel"}'::jsonb,
 '「따뜻한 라떼」의 각 낱말에서 첫 글자만 따온 말. 아이스 아메리카노를 「아아」, 따뜻한 아메리카노를 「따아」라고 부르던 카페 줄임말 체계가 라떼로 넓어진 것이다. 아메리카노 쪽이 먼저 굳었고 라떼판은 그 뒤를 따라 퍼졌다.',
 '{"en": "Built from the first syllable of each word in 따뜻한 라떼 (hot latte). It extends the café shorthand system that gave 아아 for iced americano and 따아 for hot americano; the americano forms settled first and the latte versions followed.", "ja": "「따뜻한 라떼(ホットラテ)」の各語の頭文字だけを取った語。アイスアメリカーノを「아아」、ホットアメリカーノを「따아」と呼ぶカフェ略語の体系がラテに広がったもの。アメリカーノ側が先に定着し、ラテ版が後を追って広まった。", "es": "Formada con la primera sílaba de cada palabra de 따뜻한 라떼 (latte caliente). Extiende el sistema de abreviaturas de cafetería que dio 아아 para el americano con hielo y 따아 para el caliente; las formas del americano cuajaron antes y las del latte llegaron después.", "vi": "Ghép âm đầu của từng chữ trong 따뜻한 라떼 (latte nóng). Nó nối dài hệ thống nói tắt ở quán vốn cho ra 아아 (americano đá) và 따아 (americano nóng); nhóm americano định hình trước, nhóm latte theo sau.", "de": "Aus der ersten Silbe jedes Wortes von 따뜻한 라떼 (heißer Latte) gebildet. Es setzt das Café-Kürzelsystem fort, das 아아 für Iced Americano und 따아 für heißen Americano hervorbrachte; die Americano-Formen etablierten sich zuerst, die Latte-Varianten folgten."}'::jsonb,
 '카페에서 주문할 때 쓴다. 손님끼리 또는 친한 직원에게 쓰는 편한 말이라, 처음 가는 곳에서는 못 알아듣는 경우도 있다. 짝이 되는 말은 「아라」(아이스 라떼)이며, 아메리카노 쪽은 「따아」·「아아」다.',
 '{"en": "Used when ordering. It is casual — fine between customers or with staff you know, but a first-time barista may not catch it. Its pair is 아라 (iced latte); the americano equivalents are 따아 and 아아.", "ja": "カフェで注文するときに使う。客同士や顔なじみの店員に使う砕けた言い方なので、初めての店では通じないこともある。対になる語は「아라(アイスラテ)」で、アメリカーノ側は「따아」「아아」。", "es": "Se usa al pedir. Es informal —vale entre clientes o con personal conocido—, pero en un sitio nuevo puede que no te entiendan. Su pareja es 아라 (latte con hielo); en americano son 따아 y 아아.", "vi": "Dùng khi gọi đồ. Đây là cách nói thoải mái — ổn giữa khách với nhau hay với nhân viên quen, chỗ lạ có khi họ không hiểu. Cặp của nó là 아라 (latte đá); bên americano là 따아 và 아아.", "de": "Beim Bestellen benutzt. Salopp — unter Gästen oder bei bekanntem Personal okay, in einem neuen Laden versteht man es womöglich nicht. Das Gegenstück ist 아라 (Iced Latte); beim Americano heißt es 따아 und 아아."}'::jsonb,
 'Ttara',
 '[{"type": "명사", "definition": "「따뜻한 라떼」의 줄임말. 카페 주문에서 쓰는 두 글자 약칭으로, 「아아(아이스 아메리카노)」식 조어 규칙을 따른다.", "definition_i18n": {"en": "Short for 따뜻한 라떼, hot latte — a two-syllable café order abbreviation following the same rule as 아아 (iced americano).", "ja": "「따뜻한 라떼(ホットラテ)」の略。カフェ注文で使う2文字の略称で、「아아(アイスアメリカーノ)」式の造語規則に従う。", "es": "Abreviatura de 따뜻한 라떼, latte caliente: un apócope de dos sílabas para pedir, con la misma regla que 아아 (americano con hielo).", "vi": "Viết tắt của 따뜻한 라떼, latte nóng — cách gọi hai âm khi order, theo đúng quy tắc của 아아 (americano đá).", "de": "Kurz für 따뜻한 라떼, heißer Latte — ein zweisilbiges Bestellkürzel nach derselben Regel wie 아아 (Iced Americano)."}, "examples": [{"kor": "따라 한 잔이랑 아라 한 잔 주세요.", "eng": "One hot latte and one iced latte, please.", "ja": "ホットラテ一つとアイスラテ一つください。", "es": "Un latte caliente y uno con hielo, por favor.", "vi": "Cho một latte nóng và một latte đá ạ.", "de": "Einen heißen und einen Eis-Latte, bitte."}]}]'::jsonb,
 array['아라'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Hot latte (order slang)"}, {"lang": "🇯🇵 JA", "text": "ホットラテの略"}, {"lang": "🇨🇳 ZH", "text": "热拿铁（点单缩写）"}, {"lang": "🇻🇳 VI", "text": "Latte nóng (nói tắt)"}, {"lang": "🇪🇸 ES", "text": "Latte caliente (abrev.)"}, {"lang": "🇩🇪 DE", "text": "Heißer Latte (Kürzel)"}]'::jsonb),
('432', '아라', 'daily', '아이스 라떼 — 카페 주문 줄임말', '[아라]',
 '{"en": "Iced latte — café order shorthand", "ja": "アイスラテ — カフェ注文の略語", "es": "Latte con hielo — abreviatura para pedir en el café", "vi": "Latte đá — tiếng lóng gọi đồ ở quán", "de": "Eis-Latte — Café-Bestellkürzel"}'::jsonb,
 '「아이스 라떼」의 각 낱말에서 첫 글자만 따온 말. 아이스 아메리카노를 「아아」라고 부르는 카페 줄임말 체계가 라떼로 넓어진 것으로, 「따라(따뜻한 라떼)」와 짝을 이룬다. 얼음을 선호하는 한국 카페 문화에서 주문이 잦아 줄임말이 먼저 자리 잡았다.',
 '{"en": "Built from the first syllable of each word in 아이스 라떼 (iced latte), extending the shorthand system behind 아아 (iced americano) and pairing with 따라 (hot latte). Iced drinks dominate Korean café ordering, so the cold forms took hold first.", "ja": "「아이스 라떼(アイスラテ)」の各語の頭文字だけを取った語。アイスアメリカーノを「아아」と呼ぶカフェ略語の体系がラテに広がったもので、「따라(ホットラテ)」と対をなす。氷を好む韓国のカフェ文化では注文が多く、冷たい方の略語が先に定着した。", "es": "Formada con la primera sílaba de cada palabra de 아이스 라떼 (latte con hielo); extiende el sistema de 아아 (americano con hielo) y hace pareja con 따라 (latte caliente). En la cultura cafetera coreana mandan los fríos, así que sus abreviaturas cuajaron antes.", "vi": "Ghép âm đầu của từng chữ trong 아이스 라떼 (latte đá), nối dài hệ thống của 아아 (americano đá) và đi cặp với 따라 (latte nóng). Văn hóa cà phê Hàn chuộng đồ đá nên nhóm lạnh có từ tắt trước.", "de": "Aus der ersten Silbe jedes Wortes von 아이스 라떼 (Iced Latte) gebildet, setzt das System von 아아 (Iced Americano) fort und bildet ein Paar mit 따라 (heißer Latte). In Koreas Café-Kultur dominieren kalte Getränke, deshalb setzten sich deren Kürzel zuerst durch."}'::jsonb,
 '카페에서 주문할 때 쓰는 편한 말이다. 「아라」는 사람 이름으로도 흔해서 문맥이 없으면 헷갈릴 수 있으니, 카페 밖에서는 그냥 「아이스 라떼」라고 하는 편이 안전하다. 아메리카노 쪽 짝은 「아아」다.',
 '{"en": "Casual ordering vocabulary. 아라 is also a common given name, so out of context it can be confusing — outside a café it is safer to say 아이스 라떼 in full. The americano counterpart is 아아.", "ja": "カフェで注文するときの砕けた言い方。「아라」は人名としてもよくあるので文脈がないと紛らわしく、カフェの外では「아이스 라떼」と言うほうが安全。アメリカーノ側の対は「아아」。", "es": "Vocabulario informal para pedir. 아라 es también un nombre propio frecuente, así que fuera de contexto confunde: lejos de la cafetería es más seguro decir 아이스 라떼 entero. Su equivalente en americano es 아아.", "vi": "Từ nói thoải mái khi gọi đồ. 아라 cũng là tên người phổ biến nên thiếu ngữ cảnh dễ nhầm — ra khỏi quán thì nói đủ 아이스 라떼 an toàn hơn. Bên americano là 아아.", "de": "Lockeres Bestellvokabular. 아라 ist auch ein häufiger Vorname, ohne Kontext also missverständlich — außerhalb des Cafés sagt man besser ganz 아이스 라떼. Das Americano-Pendant ist 아아."}'::jsonb,
 'Ara',
 '[{"type": "명사", "definition": "「아이스 라떼」의 줄임말. 카페 주문에서 쓰는 두 글자 약칭으로, 「아아(아이스 아메리카노)」와 같은 규칙으로 만들어졌다.", "definition_i18n": {"en": "Short for 아이스 라떼, iced latte — a two-syllable café order abbreviation made by the same rule as 아아 (iced americano).", "ja": "「아이스 라떼(アイスラテ)」の略。カフェ注文で使う2文字の略称で、「아아(アイスアメリカーノ)」と同じ規則で作られている。", "es": "Abreviatura de 아이스 라떼, latte con hielo: apócope de dos sílabas para pedir, creado con la misma regla que 아아 (americano con hielo).", "vi": "Viết tắt của 아이스 라떼, latte đá — cách gọi hai âm khi order, tạo theo đúng quy tắc của 아아 (americano đá).", "de": "Kurz für 아이스 라떼, Iced Latte — ein zweisilbiges Bestellkürzel nach derselben Regel wie 아아 (Iced Americano)."}, "examples": [{"kor": "여름엔 무조건 아라지. 따라는 못 마시겠어.", "eng": "In summer it''s iced latte, no question. I can''t do a hot one.", "ja": "夏は絶対アイスラテ。ホットは無理。", "es": "En verano, latte con hielo sí o sí. El caliente no puedo.", "vi": "Mùa hè là phải latte đá. Nóng thì chịu.", "de": "Im Sommer nur Eis-Latte. Heiß schaffe ich nicht."}]}]'::jsonb,
 array['따라'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Iced latte (order slang)"}, {"lang": "🇯🇵 JA", "text": "アイスラテの略"}, {"lang": "🇨🇳 ZH", "text": "冰拿铁（点单缩写）"}, {"lang": "🇻🇳 VI", "text": "Latte đá (nói tắt)"}, {"lang": "🇪🇸 ES", "text": "Latte con hielo (abrev.)"}, {"lang": "🇩🇪 DE", "text": "Eis-Latte (Kürzel)"}]'::jsonb),
('433', '개꿀', 'daily', '아주 좋다·수월하다', '[개꿀]',
 '{"en": "Sweet — as in this is a total win", "ja": "めちゃくちゃおいしい状況、楽勝", "es": "Chupado — un chollo total", "vi": "Ngon ơ — quá hời", "de": "Ein absoluter Zuckerschlecken"}'::jsonb,
 '강조 접두사 「개-」와 이득·편함을 뜻하는 은어 「꿀」을 합친 말. 「꿀」은 「꿀빨다」·「꿀알바」처럼 힘 안 들이고 얻는 이득을 가리키던 말이고, 여기에 「개-」가 붙어 강도가 세졌다. 「개이득」과 같은 계열이다.',
 '{"en": "The intensifier prefix 개- plus 꿀 (honey), slang for an easy gain — the same 꿀 as in 꿀빨다 (to have it easy) and 꿀알바 (a cushy job). Adding 개- cranks up the strength. It belongs to the same family as 개이득.", "ja": "強調の接頭辞「개-」と、得や楽さを意味する俗語「꿀(蜜)」を合わせた語。「꿀」は「꿀빨다」「꿀알바」のように苦労せず得る利益を指し、そこに「개-」が付いて強度が増した。「개이득」と同系列。", "es": "El prefijo intensificador 개- más 꿀 (miel), jerga para una ganancia fácil — la misma 꿀 de 꿀빨다 (tenerlo fácil) y 꿀알바 (curro cómodo). El 개- sube la intensidad. Pertenece a la familia de 개이득.", "vi": "Tiền tố nhấn mạnh 개- cộng 꿀 (mật ong), tiếng lóng chỉ cái lợi dễ dàng — cùng chữ 꿀 trong 꿀빨다 (sướng nhàn) và 꿀알바 (việc ngon). Thêm 개- thì mức độ tăng vọt. Cùng họ với 개이득.", "de": "Das Verstärkungspräfix 개- plus 꿀 (Honig), Slang für einen mühelosen Gewinn — dasselbe 꿀 wie in 꿀빨다 (es leicht haben) und 꿀알바 (bequemer Job). Das 개- dreht die Stärke hoch. Gehört zur Familie von 개이득."}'::jsonb,
 '친구끼리 쓰는 반말이다. 「개-」가 원래 거친 강조라 윗사람이나 공식적인 자리에서는 쓰지 않는다. 감탄사처럼 혼자 쓰거나(「개꿀!」) 「개꿀이다」처럼 서술어로 쓴다.',
 '{"en": "Banmal between friends. 개- is a coarse intensifier at root, so keep it away from seniors and formal settings. Use it alone like an exclamation (개꿀!) or as a predicate, 개꿀이다.", "ja": "友達同士のタメ口。「개-」はもともと荒い強調なので、目上や公式の場では使わない。感嘆詞のように単独で(「개꿀!」)、または「개꿀이다」と述語で使う。", "es": "Banmal entre amigos. 개- es de origen un intensificador basto, así que nada de superiores ni contextos formales. Se usa suelto como exclamación (¡개꿀!) o como predicado, 개꿀이다.", "vi": "Lối nói thân mật giữa bạn bè. 개- vốn là tiền tố nhấn thô, nên tránh với người trên và chỗ trang trọng. Dùng một mình như thán từ (개꿀!) hoặc làm vị ngữ, 개꿀이다.", "de": "Banmal unter Freunden. 개- ist im Kern ein derber Verstärker — also nicht gegenüber Vorgesetzten oder in formellen Situationen. Allein als Ausruf (개꿀!) oder als Prädikat, 개꿀이다."}'::jsonb,
 'Gaekkul',
 '[{"type": "명사", "definition": "힘들이지 않고 얻는 큰 이득이나 아주 수월한 상황. 「완전 이득이다」, 「거저다」에 가까운 감탄이다.", "definition_i18n": {"en": "A big gain for no effort, or a situation that turns out ridiculously easy — close to \"total win\" or \"free money\".", "ja": "苦労せずに得る大きな利益、または非常に楽な状況。「完全に得」「タダ同然」に近い感嘆。", "es": "Una ganancia grande sin esfuerzo, o una situación que sale ridículamente fácil: algo así como «chollo» o «regalado».", "vi": "Món lợi lớn mà chẳng tốn công, hoặc tình huống dễ đến vô lý — gần với \"hời quá\" hay \"như cho\".", "de": "Ein großer Gewinn ohne Aufwand oder eine lächerlich einfache Lage — nahe an „voller Gewinn“ oder „geschenkt“."}, "examples": [{"kor": "수업 휴강됐대. 개꿀!", "eng": "Class got cancelled. Sweet!", "ja": "授業休講だって。개꿀!", "es": "Se ha cancelado la clase. ¡Chupado!", "vi": "Nghe bảo nghỉ tiết. Ngon ơ!", "de": "Die Vorlesung fällt aus. Zuckerschlecken!"}]}]'::jsonb,
 array['개이득','야르바이트'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Total win / easy money"}, {"lang": "🇯🇵 JA", "text": "めっちゃ得、楽勝"}, {"lang": "🇨🇳 ZH", "text": "太爽了／白赚"}, {"lang": "🇻🇳 VI", "text": "Hời quá / dễ ăn"}, {"lang": "🇪🇸 ES", "text": "Chollo total"}, {"lang": "🇩🇪 DE", "text": "Voller Gewinn"}]'::jsonb),
('434', '고트', 'new-slang', '역대 최고', '[고트]',
 '{"en": "The greatest of all time", "ja": "史上最高", "es": "El mejor de todos los tiempos", "vi": "Vĩ đại nhất mọi thời", "de": "Der/die Größte aller Zeiten"}'::jsonb,
 '영어 「GOAT」(Greatest Of All Time, 역대 최고)를 한글로 읽은 말. 머리글자가 공교롭게 goat(염소)와 같아 영미권에서 염소 이모지 🐐로 표현하던 것이 스포츠 중계와 팬 커뮤니티를 타고 한국에 들어왔고, 이후 아이돌·게임·예능으로 넓어졌다.',
 '{"en": "The English acronym GOAT (Greatest Of All Time) read in Hangul. The initials happen to spell goat, so English-speaking fans wrote it with the 🐐 emoji; it reached Korea through sports broadcasts and fan communities and then spread to idols, gaming and variety shows.", "ja": "英語の「GOAT(Greatest Of All Time、史上最高)」をハングルで読んだ語。頭文字が偶然 goat(ヤギ)と同じで、英語圏ではヤギの絵文字🐐で表していたものが、スポーツ中継とファンコミュニティを通じて韓国に入り、その後アイドル・ゲーム・バラエティへ広がった。", "es": "El acrónimo inglés GOAT (Greatest Of All Time) leído en hangul. Las iniciales coinciden con goat (cabra), así que en el mundo anglosajón se escribía con el emoji 🐐; llegó a Corea por las retransmisiones deportivas y los fandoms, y luego se extendió a ídolos, videojuegos y programas de variedades.", "vi": "Từ viết tắt tiếng Anh GOAT (Greatest Of All Time) đọc bằng Hangul. Các chữ cái đầu tình cờ thành goat (con dê) nên fan nói tiếng Anh viết kèm emoji 🐐; nó vào Hàn qua các buổi tường thuật thể thao và cộng đồng fan, rồi lan sang idol, game, show giải trí.", "de": "Das englische Akronym GOAT (Greatest Of All Time), in Hangul gelesen. Die Initialen ergeben zufällig goat (Ziege), weshalb englischsprachige Fans das 🐐-Emoji nutzten; über Sportübertragungen und Fangemeinden kam es nach Korea und griff dann auf Idols, Gaming und Unterhaltungsshows über."}'::jsonb,
 '「그 선수는 고트야」처럼 최고라고 치켜세울 때 쓴다. 영어 표기 「GOAT」로도 그대로 쓰이는데, 국내에서는 한글로 읽어 적는 쪽이 더 흔해 이 사전은 「고트」를 표제어로 두고 「GOAT」를 검색용 이표기로 넣었다 — 어느 쪽으로 검색해도 이 항목 하나가 나온다. 진심으로 칭찬할 때도, 과장 섞어 농담할 때도 쓴다.',
 '{"en": "Used to crown someone the best, as in 그 선수는 고트야 (\"that player is the GOAT\"). The Roman spelling GOAT is used too, but the Hangul reading is more common in Korea, so this dictionary lists 고트 as the headword with GOAT as a searchable variant — either spelling finds this one entry. It works both as sincere praise and as playful exaggeration.", "ja": "「그 선수는 고트야(あの選手は史上最高だ)」のように最高だと持ち上げるときに使う。英語表記「GOAT」もそのまま使われるが、韓国ではハングルで読んで書くほうが多いため、この辞書は「고트」を見出し語にし「GOAT」を検索用の異表記として入れている — どちらで検索してもこの項目一つが出る。本気の称賛にも、大げさな冗談にも使う。", "es": "Se usa para coronar a alguien como el mejor: 그 선수는 고트야, «ese jugador es el GOAT». También se escribe GOAT en alfabeto latino, pero en Corea predomina la lectura en hangul, así que este diccionario pone 고트 como entrada y GOAT como variante buscable: con cualquiera de las dos llegas a esta misma ficha. Vale como elogio sincero y como exageración en broma.", "vi": "Dùng để tôn ai đó lên hàng số một: 그 선수는 고트야 (\"cầu thủ đó là GOAT\"). Cách viết GOAT bằng chữ Latin cũng dùng, nhưng ở Hàn đọc theo Hangul phổ biến hơn, nên từ điển này lấy 고트 làm mục từ và để GOAT làm biến thể tìm kiếm — gõ kiểu nào cũng ra đúng một mục này. Vừa là lời khen thật lòng vừa là câu đùa phóng đại.", "de": "Man krönt damit jemanden zum Besten: 그 선수는 고트야 („der Spieler ist der GOAT“). Die lateinische Schreibung GOAT kommt auch vor, doch in Korea überwiegt die Hangul-Lesung — daher führt dieses Wörterbuch 고트 als Stichwort und GOAT als suchbare Variante: Beide Schreibweisen führen zu diesem einen Eintrag. Es dient echtem Lob wie scherzhafter Übertreibung."}'::jsonb,
 'Goteu',
 '[{"type": "명사", "definition": "어떤 분야에서 역대 최고로 꼽히는 사람이나 대상. 영어 약자 GOAT(Greatest Of All Time)를 한글로 읽은 말이다.", "definition_i18n": {"en": "The person or thing considered the best ever in some field — the English acronym GOAT (Greatest Of All Time) read in Hangul.", "ja": "ある分野で史上最高とされる人や対象。英語の略語 GOAT(Greatest Of All Time)をハングルで読んだ語。", "es": "La persona o cosa considerada la mejor de la historia en algún campo: el acrónimo inglés GOAT (Greatest Of All Time) leído en hangul.", "vi": "Người hay thứ được xem là số một mọi thời trong một lĩnh vực — viết tắt tiếng Anh GOAT (Greatest Of All Time) đọc theo Hangul.", "de": "Die Person oder Sache, die in einem Bereich als die Beste aller Zeiten gilt — das englische Akronym GOAT (Greatest Of All Time), in Hangul gelesen."}, "examples": [{"kor": "이 앨범은 진짜 고트다.", "eng": "This album is genuinely the GOAT.", "ja": "このアルバムはまじで史上最高。", "es": "Este disco es de verdad el GOAT.", "vi": "Album này đúng là GOAT thật.", "de": "Dieses Album ist wirklich der GOAT."}]}]'::jsonb,
 array[]::text[], array['GOAT','고트급'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "The GOAT (greatest ever)"}, {"lang": "🇯🇵 JA", "text": "史上最高(GOAT)"}, {"lang": "🇨🇳 ZH", "text": "史上最强（GOAT）"}, {"lang": "🇻🇳 VI", "text": "GOAT (đỉnh nhất)"}, {"lang": "🇪🇸 ES", "text": "El GOAT (el mejor)"}, {"lang": "🇩🇪 DE", "text": "Der GOAT (Größter)"}]'::jsonb),
('435', '풀악셀', 'new-slang', '전력을 다해 밀어붙이는 것', '[푸락쎌]',
 '{"en": "Flooring it — going all out", "ja": "アクセル全開で突っ走ること", "es": "Pisar a fondo — ir con todo", "vi": "Đạp hết ga — dốc toàn lực", "de": "Vollgas geben — alles reinhauen"}'::jsonb,
 '영어 「full」과 자동차 가속 페달인 「악셀」(accelerator의 일본식 줄임 アクセル이 들어온 말)을 합친 표현. 페달을 끝까지 밟는다는 운전 이미지에서, 어떤 일에 속도와 힘을 최대로 쏟는다는 비유로 넓어졌다.',
 '{"en": "English full plus 악셀, the Korean word for the accelerator pedal (via Japanese アクセル). From the driving image of pressing the pedal to the floor, it widened into a metaphor for throwing maximum speed and force at something.", "ja": "英語の full と、車のアクセルペダルを指す「악셀」(日本語の「アクセル」経由)を合わせた表現。ペダルを底まで踏むという運転のイメージから、物事に速度と力を最大限注ぐという比喩へ広がった。", "es": "El inglés full más 악셀, la palabra coreana para el acelerador (vía el japonés アクセル). De la imagen de pisar el pedal hasta el fondo pasó a ser metáfora de volcar la máxima velocidad y fuerza en algo.", "vi": "Từ tiếng Anh full cộng 악셀, tức bàn đạp ga trong tiếng Hàn (qua tiếng Nhật アクセル). Từ hình ảnh đạp lún sàn, nó mở rộng thành ẩn dụ dồn hết tốc độ và sức lực vào việc gì đó.", "de": "Englisch full plus 악셀, das koreanische Wort für das Gaspedal (über japanisch アクセル). Aus dem Fahrbild, das Pedal bis zum Boden zu drücken, wurde die Metapher, mit maximalem Tempo und Kraft an etwas heranzugehen."}'::jsonb,
 '일·공부·운동처럼 힘을 쏟는 일에 두루 쓴다. 「풀악셀 밟다」 꼴이 가장 흔하다. 무모하게 몰아붙인다는 부정적 뉘앙스로도, 각오를 다지는 긍정적 뉘앙스로도 쓰이니 앞뒤 맥락으로 판단한다.',
 '{"en": "Applies broadly to work, study, training — anything you pour effort into. The commonest shape is 풀악셀 밟다 (to floor it). It carries either a negative note of reckless pushing or a positive one of steeling yourself, so read the surrounding context.", "ja": "仕事・勉強・運動など力を注ぐこと全般に使う。「풀악셀 밟다(アクセル全開で踏む)」の形が最も多い。無謀に突っ走るという否定的なニュアンスにも、覚悟を固める肯定的なニュアンスにも使われるので前後の文脈で判断する。", "es": "Vale para trabajo, estudio, entrenamiento: cualquier cosa a la que le metas esfuerzo. La forma más común es 풀악셀 밟다, pisar a fondo. Puede sonar negativo (forzar sin cabeza) o positivo (armarse de determinación), así que hay que mirar el contexto.", "vi": "Dùng rộng cho công việc, học hành, tập luyện — bất cứ thứ gì bạn dồn sức. Dạng phổ biến nhất là 풀악셀 밟다 (đạp hết ga). Nó có thể mang sắc thái tiêu cực là lao đầu liều lĩnh, hoặc tích cực là quyết tâm, nên phải xem ngữ cảnh.", "de": "Gilt breit für Arbeit, Lernen, Training — alles, in das man Kraft steckt. Am häufigsten als 풀악셀 밟다 (Vollgas geben). Es kann negativ nach kopflosem Durchdrücken klingen oder positiv nach Entschlossenheit — der Kontext entscheidet."}'::jsonb,
 'Puchaksel',
 '[{"type": "명사", "definition": "가속 페달을 끝까지 밟듯이 어떤 일에 속도와 힘을 최대로 쏟아붓는 것. 「풀악셀 밟다」 꼴로 자주 쓴다.", "definition_i18n": {"en": "Throwing maximum speed and force at something, the way you press the accelerator all the way down. Usually appears as 풀악셀 밟다.", "ja": "アクセルを底まで踏むように、物事に速度と力を最大限注ぎ込むこと。「풀악셀 밟다」の形でよく使う。", "es": "Volcar la máxima velocidad y fuerza en algo, como quien pisa el acelerador hasta el fondo. Suele aparecer como 풀악셀 밟다.", "vi": "Dồn tối đa tốc độ và sức lực vào việc gì đó, như đạp ga lún sàn. Thường ở dạng 풀악셀 밟다.", "de": "Höchsttempo und volle Kraft in etwas stecken, wie wenn man das Gaspedal durchtritt. Meist als 풀악셀 밟다."}, "examples": [{"kor": "마감 이틀 남아서 지금 풀악셀 밟는 중이야.", "eng": "Two days to the deadline — I''m flooring it right now.", "ja": "締め切りまで2日だから今アクセル全開。", "es": "Quedan dos días para la entrega, voy pisando a fondo.", "vi": "Còn hai ngày tới hạn nên giờ đang đạp hết ga.", "de": "Zwei Tage bis zur Deadline — ich gebe gerade Vollgas."}]}]'::jsonb,
 array['급발진'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Go all out / floor it"}, {"lang": "🇯🇵 JA", "text": "アクセル全開"}, {"lang": "🇨🇳 ZH", "text": "全力冲刺"}, {"lang": "🇻🇳 VI", "text": "Đạp hết ga"}, {"lang": "🇪🇸 ES", "text": "Pisar a fondo"}, {"lang": "🇩🇪 DE", "text": "Vollgas geben"}]'::jsonb),
('436', '급발진', 'new-slang', '갑자기 감정이 확 폭주하는 것', '[급빨찐]',
 '{"en": "Suddenly flooring it emotionally, out of nowhere", "ja": "突然感情が暴走すること", "es": "Arrancar de golpe emocionalmente", "vi": "Bỗng dưng bốc lên đùng đùng", "de": "Emotional plötzlich losschießen"}'::jsonb,
 '원래는 차가 운전자의 의도와 무관하게 갑자기 튀어 나가는 자동차 결함을 가리키는 말. 2010년대 후반 이 사고가 크게 보도되며 널리 알려졌고, 「의도치 않게 갑자기 확 나간다」는 이미지가 사람의 감정과 언행에 옮겨 붙어 신조어 용법이 생겼다.',
 '{"en": "Originally the automotive defect in which a car lurches forward regardless of the driver''s intent. Heavy news coverage in the late 2010s made the term familiar, and the image of shooting off suddenly and unintentionally transferred to people''s emotions and behaviour, producing the slang sense.", "ja": "もともとは運転者の意図と関係なく車が突然飛び出す自動車の欠陥を指す語。2010年代後半にこの事故が大きく報道されて広く知られ、「意図せず急に飛び出す」というイメージが人の感情や言動に移って新語用法が生まれた。", "es": "En origen, el fallo del automóvil por el que el coche sale disparado al margen de la intención del conductor. La fuerte cobertura mediática de finales de los 2010 popularizó el término, y la imagen de salir disparado de golpe y sin querer se trasladó a las emociones y la conducta, dando el uso coloquial.", "vi": "Vốn là lỗi kỹ thuật khiến xe vọt lên bất kể tài xế có đạp ga hay không. Báo chí đưa tin dày đặc cuối thập niên 2010 khiến từ này quen thuộc, rồi hình ảnh \"bất ngờ vọt đi ngoài ý muốn\" chuyển sang cảm xúc và hành vi con người, sinh ra nghĩa lóng.", "de": "Ursprünglich der Fahrzeugdefekt, bei dem ein Auto unabhängig vom Willen des Fahrers vorschießt. Intensive Berichterstattung Ende der 2010er machte den Begriff geläufig, und das Bild vom plötzlichen, ungewollten Losschießen übertrug sich auf Gefühle und Verhalten — daraus entstand die Slang-Bedeutung."}'::jsonb,
 '차분하던 사람이 갑자기 화내거나 흥분해서 말이 확 세질 때 쓴다. 「급발진했다」 꼴이 흔하다. 놀리는 뉘앙스가 있어 본인 앞에서 쓰면 기분 상할 수 있고, 자기 얘기로 「나 방금 급발진했네」처럼 쓰면 자연스럽다.',
 '{"en": "Said when someone calm abruptly gets angry or worked up and their words spike. Usually 급발진했다. It carries a teasing note, so it can sting said to the person''s face; about yourself — 나 방금 급발진했네 — it lands naturally.", "ja": "落ち着いていた人が急に怒ったり興奮して言葉がきつくなるときに使う。「급발진했다」の形が多い。からかいのニュアンスがあるので本人の前で言うと気を悪くすることがあり、自分のこととして「나 방금 급발진했네(今ちょっと暴走した)」と言うと自然。", "es": "Se dice cuando alguien tranquilo se enfada o se acelera de golpe y sube el tono. Suele ser 급발진했다. Tiene un matiz burlón, así que a la cara puede molestar; sobre uno mismo —나 방금 급발진했네— queda natural.", "vi": "Nói khi người đang bình thản bỗng nổi giận hay phấn khích khiến lời lẽ gắt hẳn lên. Thường là 급발진했다. Có sắc thái trêu chọc nên nói thẳng mặt dễ mếch lòng; nói về mình — 나 방금 급발진했네 — thì tự nhiên.", "de": "Gesagt, wenn jemand Ruhiges plötzlich wütend oder aufgedreht wird und im Ton hochschießt. Meist 급발진했다. Es klingt neckend und kann ins Gesicht gesagt verletzen; über sich selbst — 나 방금 급발진했네 — wirkt es natürlich."}'::jsonb,
 'Geupbaljin',
 '[{"type": "명사", "definition": "차분하던 사람이 갑자기 감정이 격해져 화를 내거나 말이 세지는 것. 차가 갑자기 튀어 나가는 자동차 급발진 사고에 빗댄 말이다.", "definition_i18n": {"en": "A calm person''s sudden surge into anger or sharp words — likened to a car lurching forward on its own in a sudden-acceleration incident.", "ja": "落ち着いていた人が急に感情が高ぶって怒ったり言葉がきつくなること。車が突然飛び出す急発進事故に例えた語。", "es": "El arranque súbito de enfado o de palabras cortantes en alguien que estaba tranquilo, comparado con el coche que sale disparado solo.", "vi": "Việc một người đang bình thản bỗng dâng cảm xúc mà nổi nóng hay nói gắt — ví như xe tự vọt lên trong sự cố tăng tốc đột ngột.", "de": "Der plötzliche Ausbruch von Wut oder scharfen Worten bei einer ruhigen Person — verglichen mit einem Auto, das von selbst vorschießt."}, "examples": [{"kor": "갑자기 왜 급발진해? 그냥 물어본 건데.", "eng": "Why the sudden blow-up? I was just asking.", "ja": "何で急に暴走するの?ただ聞いただけなのに。", "es": "¿A qué viene ese arranque? Solo preguntaba.", "vi": "Sao tự dưng bốc lên thế? Tớ chỉ hỏi thôi mà.", "de": "Warum schießt du plötzlich so los? Ich hab nur gefragt."}]}]'::jsonb,
 array['풀악셀','빡치다'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Sudden emotional blow-up"}, {"lang": "🇯🇵 JA", "text": "感情の急発進"}, {"lang": "🇨🇳 ZH", "text": "情绪突然暴冲"}, {"lang": "🇻🇳 VI", "text": "Bỗng bốc hỏa"}, {"lang": "🇪🇸 ES", "text": "Arranque de golpe"}, {"lang": "🇩🇪 DE", "text": "Plötzlicher Ausraster"}]'::jsonb),
('437', '멘탈증발', 'new-slang', '정신이 통째로 날아간 상태', '[멘탈쯩발]',
 '{"en": "Your mental state evaporating on the spot", "ja": "メンタルが丸ごと蒸発した状態", "es": "Que se te evapore la cabeza del todo", "vi": "Tinh thần bốc hơi sạch", "de": "Wenn die Nerven schlicht verdampfen"}'::jsonb,
 '영어 「mental」을 그대로 쓴 「멘탈」에 「증발(蒸發)」을 붙인 말. 앞서 자리 잡은 「멘붕」(멘탈 붕괴)의 계열어로, 무너지는 것을 넘어 흔적도 없이 날아갔다는 쪽으로 강도를 한 단계 올린 표현이다.',
 '{"en": "멘탈, the English word mental used as a noun, plus 증발 (evaporation). It belongs to the family of the earlier 멘붕 (mental collapse) and turns the dial up a notch: not merely collapsing but vanishing without a trace.", "ja": "英語の mental をそのまま使った「멘탈」に「증발(蒸発)」を付けた語。先に定着した「멘붕(メンタル崩壊)」の系列語で、崩れるどころか跡形もなく飛んだという方向に強度を一段上げた表現。", "es": "멘탈, el inglés mental usado como sustantivo, más 증발 (evaporación). Pertenece a la familia del anterior 멘붕 (colapso mental) y sube un peldaño: no es que se derrumbe, es que desaparece sin dejar rastro.", "vi": "멘탈, tức chữ mental tiếng Anh dùng như danh từ, cộng 증발 (bốc hơi). Thuộc họ của 멘붕 (sụp đổ tinh thần) có trước và nâng mức độ lên một nấc: không chỉ sụp mà bay hơi không còn dấu vết.", "de": "멘탈, das englische mental als Substantiv, plus 증발 (Verdampfen). Es gehört zur Familie des älteren 멘붕 (mentaler Zusammenbruch) und legt eine Stufe drauf: nicht bloß einstürzen, sondern spurlos verschwinden."}'::jsonb,
 '충격받은 순간을 과장해서 말할 때 쓰는 반말이다. 시험을 망쳤거나 실수를 크게 했을 때처럼 자기 상태를 알릴 때 자연스럽다. 이미 등록된 「멘붕」과 뜻이 겹치지만 더 세게 말하고 싶을 때 고른다.',
 '{"en": "Banmal for exaggerating a moment of shock. It sits naturally when reporting your own state after bombing an exam or making a big mistake. It overlaps with the already-listed 멘붕, and you reach for it when you want the stronger of the two.", "ja": "ショックを受けた瞬間を大げさに言うときのタメ口。試験を失敗した、大きなミスをしたなど自分の状態を伝えるときに自然。既に収録済みの「멘붕」と意味が重なるが、より強く言いたいときに選ぶ。", "es": "Banmal para exagerar un momento de shock. Encaja al contar tu propio estado tras suspender un examen o meter la pata a lo grande. Se solapa con 멘붕, ya recogido aquí, y se elige cuando quieres la versión más fuerte.", "vi": "Lối nói thân mật để phóng đại khoảnh khắc choáng váng. Hợp khi kể tình trạng của mình sau khi thi hỏng hay mắc lỗi lớn. Nghĩa chồng lấn với 멘붕 đã có trong từ điển, và bạn chọn nó khi muốn nói nặng hơn.", "de": "Banmal, um einen Schockmoment zu übertreiben. Passt, wenn man den eigenen Zustand nach einer verhauenen Prüfung oder einem großen Fehler schildert. Es überschneidet sich mit dem bereits verzeichneten 멘붕 und ist die stärkere Wahl."}'::jsonb,
 'Mental Jeungbal',
 '[{"type": "명사", "definition": "충격이나 당황으로 정신이 아예 날아가 아무 생각도 안 나는 상태. 「멘붕」보다 한 단계 센 말이다.", "definition_i18n": {"en": "Being so shocked or flustered that your mind is simply gone and nothing comes to you — a notch stronger than 멘붕.", "ja": "衝撃や動揺で意識が完全に飛び、何も考えられない状態。「멘붕」より一段強い語。", "es": "Estar tan conmocionado o aturdido que la mente se va del todo y no te viene nada: un grado más fuerte que 멘붕.", "vi": "Choáng hoặc luống cuống tới mức đầu óc bay sạch, chẳng nghĩ ra gì — mạnh hơn 멘붕 một nấc.", "de": "So geschockt oder durcheinander, dass der Kopf schlicht weg ist und einem nichts einfällt — eine Stufe stärker als 멘붕."}, "examples": [{"kor": "발표 중에 파일이 안 열려서 멘탈증발했어.", "eng": "The file wouldn''t open mid-presentation — my brain just evaporated.", "ja": "発表中にファイルが開かなくてメンタル蒸発した。", "es": "En mitad de la presentación no se abría el archivo: se me evaporó la cabeza.", "vi": "Đang thuyết trình mà file không mở được, tinh thần bốc hơi luôn.", "de": "Mitten in der Präsentation ging die Datei nicht auf — mein Kopf ist verdampft."}]}]'::jsonb,
 array['멘붕','뇌정지'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Mind completely gone"}, {"lang": "🇯🇵 JA", "text": "メンタル蒸発"}, {"lang": "🇨🇳 ZH", "text": "心态直接蒸发"}, {"lang": "🇻🇳 VI", "text": "Tinh thần bốc hơi"}, {"lang": "🇪🇸 ES", "text": "Cabeza evaporada"}, {"lang": "🇩🇪 DE", "text": "Nerven verdampft"}]'::jsonb),
('438', '뇌정지', 'new-slang', '머리가 멈춰 아무 생각도 안 나는 순간', '[뇌정지]',
 '{"en": "The moment your brain just stops", "ja": "頭が止まって何も考えられない瞬間", "es": "El momento en que el cerebro se te para", "vi": "Khoảnh khắc não đứng hình", "de": "Der Moment, in dem das Hirn stehenbleibt"}'::jsonb,
 '「뇌(腦)」와 기계가 멈춘다는 뜻의 「정지(停止)」를 합친 말. 컴퓨터나 기계가 멈춰 서는 이미지를 사람 머리에 그대로 옮겼다. 「멘붕」이 감정이 무너지는 쪽이라면 이 말은 사고가 그 자리에서 멎는 쪽을 가리킨다.',
 '{"en": "뇌 (brain) plus 정지 (a halt, as of a machine). It maps the image of a computer or machine freezing directly onto a person''s head. Where 멘붕 is about feelings collapsing, this one is about thought stopping dead.", "ja": "「뇌(脳)」と機械が止まることを意味する「정지(停止)」を合わせた語。コンピュータや機械が止まるイメージを人の頭にそのまま移した。「멘붕」が感情の崩壊なら、この語は思考がその場で止まることを指す。", "es": "뇌 (cerebro) más 정지 (parada, como la de una máquina). Traslada al cerebro humano la imagen de un ordenador que se congela. Si 멘붕 va de emociones que se desmoronan, esta va de pensamiento que se detiene en seco.", "vi": "뇌 (não) cộng 정지 (dừng lại, như máy móc). Nó đưa hình ảnh máy tính treo cứng thẳng vào đầu người. Nếu 멘붕 là cảm xúc sụp đổ thì từ này là suy nghĩ đứng khựng tại chỗ.", "de": "뇌 (Gehirn) plus 정지 (Stillstand wie bei einer Maschine). Es überträgt das Bild eines einfrierenden Computers direkt auf den menschlichen Kopf. Wo 멘붕 den Zusammenbruch der Gefühle meint, meint dieses Wort das abrupte Stocken des Denkens."}'::jsonb,
 '예상 못 한 질문을 받았거나 계산이 꼬였을 때처럼 순간적으로 머리가 하얘진 상황에 쓴다. 「뇌정지 왔다」 꼴이 흔하다. 감정이 무너진 쪽이면 「멘붕」·「멘탈증발」이 더 맞다.',
 '{"en": "Used for the instant your mind goes blank — an unexpected question, a calculation that tangles. Commonly 뇌정지 왔다 (\"brain-freeze hit\"). If it is your feelings that gave way, 멘붕 or 멘탈증발 fits better.", "ja": "予想外の質問を受けたときや計算がこんがらがったときなど、一瞬頭が真っ白になる状況に使う。「뇌정지 왔다」の形が多い。感情が崩れたほうなら「멘붕」「멘탈증발」が合う。", "es": "Se usa para el instante en que la mente se queda en blanco: una pregunta inesperada, una cuenta que se enreda. Suele ser 뇌정지 왔다. Si lo que cede son las emociones, encajan mejor 멘붕 o 멘탈증발.", "vi": "Dùng cho khoảnh khắc đầu óc trống rỗng — bị hỏi bất ngờ, tính toán rối tung. Thường là 뇌정지 왔다. Nếu là cảm xúc sụp đổ thì 멘붕 hay 멘탈증발 hợp hơn.", "de": "Für den Augenblick, in dem der Kopf leer wird — eine unerwartete Frage, eine verhedderte Rechnung. Meist 뇌정지 왔다. Wenn eher die Gefühle nachgeben, passen 멘붕 oder 멘탈증발 besser."}'::jsonb,
 'Noejeongji',
 '[{"type": "명사", "definition": "갑작스러운 상황에 생각이 뚝 멈춰 머리가 하얘지는 것. 기계가 멈추듯 사고가 정지한다는 비유다.", "definition_i18n": {"en": "Thought cutting out and the mind going blank in a sudden situation — a metaphor of cognition halting like a machine.", "ja": "突然の状況で考えがぷつりと止まり頭が真っ白になること。機械が止まるように思考が停止するという比喩。", "es": "El pensamiento que se corta y la mente en blanco ante una situación repentina: metáfora de la cognición parándose como una máquina.", "vi": "Suy nghĩ đứt phựt và đầu trống rỗng trước tình huống bất ngờ — ẩn dụ nhận thức dừng như máy móc.", "de": "Das Denken setzt aus und der Kopf wird leer in einer plötzlichen Lage — eine Metapher für Kognition, die wie eine Maschine anhält."}, "examples": [{"kor": "면접에서 그 질문 듣고 뇌정지 왔어.", "eng": "That question in the interview gave me total brain freeze.", "ja": "面接でその質問を聞いて頭が真っ白になった。", "es": "Con esa pregunta en la entrevista se me paró el cerebro.", "vi": "Nghe câu hỏi đó trong buổi phỏng vấn là não đứng hình luôn.", "de": "Bei der Frage im Vorstellungsgespräch hatte ich totalen Blackout."}]}]'::jsonb,
 array['멘붕','멘탈증발'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Brain freeze / mind blank"}, {"lang": "🇯🇵 JA", "text": "頭が真っ白"}, {"lang": "🇨🇳 ZH", "text": "大脑宕机"}, {"lang": "🇻🇳 VI", "text": "Não đứng hình"}, {"lang": "🇪🇸 ES", "text": "Cerebro parado"}, {"lang": "🇩🇪 DE", "text": "Blackout im Kopf"}]'::jsonb);

